SUPPORTED_PAYMENT_METHODS = ('credit_card', 'paypal', 'bank_transfer')


def process_payment(user, cart, payment_method):
    if user is None:
        return {'status': 'error', 'reason': 'user not found'}
    if not user.get('is_active'):
        return {'status': 'error', 'reason': 'inactive user'}
    if not cart or not cart.get('items'):
        return {'status': 'error', 'reason': 'empty cart'}
    if payment_method not in SUPPORTED_PAYMENT_METHODS:
        return {'status': 'error', 'reason': 'unsupported payment method'}
    total = sum(i['price'] * i['qty'] for i in cart['items'])
    if total <= 0:
        return {'status': 'error', 'reason': 'zero total'}
    if payment_method == 'credit_card' and not user.get('credit_card_verified'):
        return {'status': 'error', 'reason': 'card not verified'}
    return {'status': 'charged', 'amount': total}

