import os

ALLOWED_EXTENSIONS = ('.jpg', '.png', '.pdf', '.docx', '.xlsx')


def upload_file(file_path, destination_bucket, user_permissions, max_size_mb):
    if not os.path.exists(file_path):
        return {'status': 'error', 'reason': 'file not found'}
    if not os.path.isfile(file_path):
        return {'status': 'error', 'reason': 'path is not a file'}
    size_mb = os.path.getsize(file_path) / (1024 * 1024)
    if size_mb > max_size_mb:
        return {'status': 'error', 'reason': f'file too large: {size_mb:.1f}MB'}
    ext = os.path.splitext(file_path)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return {'status': 'error', 'reason': f'unsupported file type: {ext}'}
    if 'upload' not in user_permissions:
        return {'status': 'error', 'reason': 'permission denied'}
    if not destination_bucket:
        return {'status': 'error', 'reason': 'no destination bucket'}
    return {
        'status': 'uploaded',
        'path': file_path,
        'bucket': destination_bucket,
        'size_mb': round(size_mb, 2),
    }

