from datetime import date


def apply_coupon(coupon, order_total, user_tier, today):
    if coupon is None:
        return {'applied': False, 'reason': 'no coupon provided'}
    if not coupon.get('active'):
        return {'applied': False, 'reason': 'coupon inactive'}
    if today > coupon.get('expiry_date', date.max):
        return {'applied': False, 'reason': 'coupon expired'}
    if order_total < coupon.get('min_order', 0):
        return {'applied': False, 'reason': 'order below minimum'}
    if user_tier not in coupon.get('eligible_tiers', ['bronze', 'silver', 'gold']):
        return {'applied': False, 'reason': 'tier not eligible'}
    discount = order_total * coupon['discount_pct']
    capped = coupon.get('max_discount')
    if capped is not None:
        discount = min(discount, capped)
    return {'applied': True, 'discount': round(discount, 2)}

