SUPPORTED_PLATFORMS = ('ios', 'android', 'web')
MIN_APP_MAJOR_VERSION = 2
MIN_PUSH_TOKEN_LENGTH = 32


def register_device(device_id, platform, app_version, push_token, user_id):
    if not device_id:
        return {'registered': False, 'reason': 'missing device_id'}
    if platform not in SUPPORTED_PLATFORMS:
        return {'registered': False, 'reason': 'unsupported platform'}
    parts = app_version.split('.')
    if len(parts) != 3 or not all(p.isdigit() for p in parts):
        return {'registered': False, 'reason': 'invalid version format'}
    if int(parts[0]) < MIN_APP_MAJOR_VERSION:
        return {'registered': False, 'reason': 'app version too old'}
    if not push_token or len(push_token) < MIN_PUSH_TOKEN_LENGTH:
        return {'registered': False, 'reason': 'invalid push token'}
    if not user_id:
        return {'registered': False, 'reason': 'missing user_id'}
    return {'registered': True, 'device_id': device_id, 'platform': platform, 'user_id': user_id}
